SET XACT_ABORT ON;

-- Đảm bảo session không còn bật IDENTITY_INSERT từ lần chạy script bị lỗi trước đó.
IF OBJECT_ID('dap_an', 'U') IS NOT NULL SET IDENTITY_INSERT dap_an OFF;
IF OBJECT_ID('cau_hoi', 'U') IS NOT NULL SET IDENTITY_INSERT cau_hoi OFF;
IF OBJECT_ID('files', 'U') IS NOT NULL SET IDENTITY_INSERT files OFF;
IF OBJECT_ID('file_usages', 'U') IS NOT NULL SET IDENTITY_INSERT file_usages OFF;

IF COL_LENGTH('de_thi', 'loai_de_thi') IS NULL
BEGIN
    EXEC(N'ALTER TABLE de_thi ADD loai_de_thi NVARCHAR(50) NULL;');
END;

IF COL_LENGTH('de_thi', 'loai_de_thi') IS NOT NULL
BEGIN
    EXEC(N'UPDATE de_thi SET loai_de_thi = ISNULL(loai_de_thi, N''thi_thu'');');
END;

IF COL_LENGTH('cau_hoi', 'giai_thich_dap_an') IS NULL
BEGIN
    EXEC(N'ALTER TABLE cau_hoi ADD giai_thich_dap_an NVARCHAR(2000) NULL;');
END;

BEGIN TRANSACTION;

DELETE FROM chi_tiet_bai_thi;
DELETE FROM phien_on_tap_cau_hoi;
DELETE FROM de_thi_cau_hoi;

IF OBJECT_ID('file_usages', 'U') IS NOT NULL
BEGIN
    DELETE FROM file_usages
    WHERE entity_name = 'cau_hoi';
END;

IF OBJECT_ID('files', 'U') IS NOT NULL
BEGIN
    DELETE FROM files
    WHERE public_url LIKE '/assets/%';
END;

DELETE FROM dap_an;
DELETE FROM cau_hoi;

