INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (277, 88, N'Xe mô tô hai bánh có dung tích xi-lanh trên 125 cm3 hoặc có công suất động cơ điện trên 11 kW.', 0, 2);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (278, 88, N'Cả hai ý trên.', 1, 3);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (279, 89, N'Phải đủ tuổi, sức khỏe theo quy định của pháp luật; có giấy phép lái xe đang còn điểm, còn hiệu lực phù hợp với loại xe đang điều khiển do cơ quan có thẩm quyền cấp (trừ người lái xe gắn máy).', 1, 1);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (280, 89, N'Phải là người đứng tên trong đăng ký xe.', 0, 2);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (281, 89, N'Cả hai ý trên.', 0, 3);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (282, 90, N'Chứng nhận đăng ký xe hoặc bản sao Chứng nhận đăng ký xe có chứng thực kèm bản gốc giấy tờ xác nhận của tổ chức tín dụng, chi nhánh ngân hàng nước ngoài còn hiệu lực trong trường hợp xe đang được thế chấp tại tổ chức tín dụng, chi nhánh ngân hàng nước ngoài.', 0, 1);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (283, 90, N'Giấy phép lái xe phù hợp với loại xe đang điều khiển; chứng nhận kiểm định an toàn kỹ thuật và bảo vệ môi trường đối với xe cơ giới theo quy định của pháp luật; chứng nhận bảo hiểm bắt buộc trách nhiệm dân sự của chủ xe cơ giới.', 0, 2);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (284, 90, N'Trường hợp các giấy tờ nêu trên đã được tích hợp vào tài khoản định danh điện tử thì việc xuất trình, kiểm tra có thể thực hiện thông qua tài khoản định danh điện tử.', 0, 3);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (285, 90, N'Cả ba ý trên.', 1, 4);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (286, 91, N'Không được phục hồi.', 0, 1);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (287, 91, N'Được phục hồi đủ 12 điểm, nếu không bị trừ điểm trong thời hạn 12 tháng từ ngày bị trừ điểm gần nhất.', 1, 2);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (288, 92, N'Không vi phạm pháp luật trật tự, an toàn giao thông đường bộ trong thời gian 12 tháng kể từ ngày bị trừ hết điểm.', 0, 1);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (289, 92, N'Sau thời hạn ít nhất là 06 tháng kể từ ngày bị trừ hết điểm, người có phép lái xe được tham gia kiểm tra nội dung kiến thức pháp luật về trật tự, an toàn giao thông đường bộ theo quy định, có kết quả đạt yêu cầu thì được phục hồi đủ 12 điểm.', 1, 2);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (290, 92, N'Cả hai ý trên.', 0, 3);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (291, 93, N'Tiếp tục chịu trách nhiệm của chủ xe.', 1, 1);
INSERT INTO dap_an (id, cau_hoi_id, noi_dung, la_dap_an_dung, thu_tu) VALUES (292, 93, N'Không chịu trách nhiệm sau khi đã chuyển nhượng, trao đổi, tặng, cho.', 0, 2);
